(function(){
const {escape:esc}=PortfolioCMS;
const numeric=[['frameSize','Frame size',70,130,'%'],['frameX','Frame horizontal offset',-25,25,'%'],['frameY','Frame vertical offset',-20,20,'%'],['rotation','Frame tilt',-15,15,'°'],['corners','Frame corner radius',0,30,'px'],['shadow','Frame shadow',0,60,'%'],['imageZoom','Image zoom',100,220,'%'],['imageX','Image horizontal crop',0,100,'%'],['imageY','Image vertical crop',0,100,'%']];
function slider(p,key,label,min,max,unit){return `<label><span class="range-heading"><span>${label}</span><output for="cover-${key}">${p[key]}${unit}</output></span><input id="cover-${key}" data-cover-number="${key}" type="range" min="${min}" max="${max}" value="${p[key]}"></label>`;}
function panel(project){const p=ProjectCovers.config(project);return `<section class="cover-workbench"><div class="cover-workbench-heading"><div><span class="eyebrow">DESIGN YOUR PROJECT COVER</span><h2>A frame for your work.</h2></div><span class="cover-preview-badge">LIVE PREVIEW</span></div><div class="template-picker" role="group" aria-label="Project cover templates">${Object.entries(ProjectCovers.types).map(([key,label])=>`<button type="button" class="template-option${p.template===key?' selected':''}" data-cover-template="${key}" aria-pressed="${p.template===key}" aria-label="Template: ${label}"><span class="template-thumb thumb-${key}" aria-hidden="true"><i></i><b></b></span><span>${label}</span></button>`).join('')}</div><div class="cover-workbench-grid"><aside class="cover-preview-sticky"><div id="project-template-preview" role="img" aria-label="Live project cover preview"></div><p class="hint">The same layout is used on the portfolio. Your source image is preserved; these controls change its presentation.</p><p id="template-image-status" class="hint" role="status"></p></aside><div class="cover-design-controls"><div class="field-pair"><label>Upload a project image<input id="cover-upload" type="file" accept="image/jpeg,image/png,image/webp,image/avif"></label><label>Pastel background<select id="project-color">${['lilac','mint','peach','yellow'].map(c=>`<option ${project.cover_color===c?'selected':''}>${c}</option>`).join('')}</select></label></div><label>Image URL<input id="project-cover" type="text" maxlength="2000" value="${esc(project.cover_url||'')}" placeholder="https://… or /assets/…"></label><img id="cover-preview" alt="Source image preview" hidden><p class="hint">JPG, PNG, WebP, or AVIF, up to 10 MB. Add a screenshot or leave the image blank for a built-in illustration.</p><details open><summary>Cover text</summary><label>Small heading<input id="cover-eyebrow" data-cover-text="eyebrow" maxlength="150" value="${esc(p.eyebrow)}"></label><label>Headline · one line per row<textarea id="cover-headline" data-cover-text="headline" rows="3" maxlength="150">${esc(p.headline)}</textarea></label><div class="field-pair"><label>Footer label<input id="cover-footer" data-cover-text="footer" maxlength="150" value="${esc(p.footer)}"></label><label>Window label<input id="cover-windowLabel" data-cover-text="windowLabel" maxlength="100" value="${esc(p.windowLabel)}"></label></div><label id="terminal-copy-wrap" ${p.template!=='terminal'?'hidden':''}>Terminal text · used when no image is selected<textarea id="cover-terminalText" data-cover-text="terminalText" rows="5" maxlength="1500">${esc(p.terminalText)}</textarea></label></details><details><summary>Frame position & style</summary><div class="cover-ranges">${numeric.slice(0,6).map(args=>slider(p,...args)).join('')}</div><p class="hint">Device templates keep their distinctive watch or phone shape. Corner radius adjusts browser and terminal frames.</p></details><details><summary>Image crop & fit</summary><label>Image fit<select id="cover-fit"><option value="cover" ${p.fit==='cover'?'selected':''}>Fill screen · crop edges</option><option value="contain" ${p.fit==='contain'?'selected':''}>Show full image · fit inside</option></select></label><div class="cover-ranges">${numeric.slice(6).map(args=>slider(p,...args)).join('')}</div></details><button type="button" id="reset-cover-frame" class="secondary-button">Reset frame & crop</button><span class="hint">Save the project below to apply this design.</span></div></div></section>`;}
let active=null;
function mount(form,project,dirty){const current=ProjectCovers.config(project);active={form,template:current.template,project,dirty};const read=()=>{const raw={template:active.template};form.querySelectorAll('[data-cover-text]').forEach(input=>raw[input.dataset.coverText]=input.value);form.querySelectorAll('[data-cover-number]').forEach(input=>raw[input.dataset.coverNumber]=Number(input.value));raw.fit=form.querySelector('#cover-fit').value;return ProjectCovers.config({...project,cover_layout:raw})};active.read=read;function preview(){const p=read();form.querySelector('#project-template-preview').innerHTML=ProjectCovers.render({...project,title:form.querySelector('#project-title')?.value||project.title,cover_url:form.querySelector('#project-cover').value,cover_color:form.querySelector('#project-color').value,cover_layout:p});for(const [key,,,,unit]of numeric){const input=form.querySelector('#cover-'+key);input.closest('label').querySelector('output').textContent=input.value+unit}form.querySelector('#terminal-copy-wrap').hidden=p.template!=='terminal';const img=form.querySelector('#project-template-preview img'),status=form.querySelector('#template-image-status');status.textContent='';if(img){img.addEventListener('error',()=>status.textContent='This image could not load. Check its URL or upload another image.');}form.querySelectorAll('[data-cover-template]').forEach(button=>{const selected=button.dataset.coverTemplate===p.template;button.classList.toggle('selected',selected);button.setAttribute('aria-pressed',String(selected))});}
form.querySelectorAll('[data-cover-template]').forEach(button=>button.addEventListener('click',()=>{const old=read(),next=ProjectCovers.presets[button.dataset.coverTemplate];active.template=next.template;for(const [key]of numeric)form.querySelector('#cover-'+key).value=next[key];form.querySelector('#cover-fit').value=next.fit;const previous=ProjectCovers.presets[old.template];for(const key of ['eyebrow','headline','footer','windowLabel','terminalText']){const input=form.querySelector('#cover-'+key);if(input.value===previous[key])input.value=next[key]}dirty();preview()}));
form.addEventListener('input',preview);form.addEventListener('change',preview);form.querySelector('#reset-cover-frame').addEventListener('click',()=>{const preset=ProjectCovers.presets[active.template];for(const [key]of numeric)form.querySelector('#cover-'+key).value=preset[key];form.querySelector('#cover-fit').value=preset.fit;dirty();preview()});active.preview=preview;preview();}
window.ProjectCoverEditor={panel,mount,read:()=>active.read(),refresh:()=>active?.preview()};
})();
